function ccv5_add_column(PDO $pdo,string $name,string $definition): void {
  try{$st=$pdo->prepare('SHOW COLUMNS FROM surf_beta_subscribers LIKE ?');$st->execute([$name]);if(!$st->fetch())$pdo->exec('ALTER TABLE surf_beta_subscribers ADD COLUMN '.$name.' '.$definition);}catch(Throwable $e){}
}
ccv5_add_column($pdo,'origin_postcode','VARCHAR(8) NULL AFTER origin_lon');
ccv5_add_column($pdo,'location_source','VARCHAR(20) NULL AFTER origin_postcode');
ccv5_add_column($pdo,'schedule_mode','VARCHAR(30) NULL AFTER location_source');
ccv5_add_column($pdo,'schedule_hour','DECIMAL(4,2) NULL AFTER schedule_mode');
ccv5_add_column($pdo,'session_minutes','SMALLINT UNSIGNED NULL AFTER schedule_hour');
ccv5_add_column($pdo,'buffer_minutes','SMALLINT UNSIGNED NULL AFTER session_minutes');

function ccv5_secret(): string {$c=cc_config();return hash('sha256','surf-beta-v2|'.($c['db_pass']??'fallback').'|costacams');}
function ccv5_token(int $id,string $email,string $purpose): string {$sig=hash_hmac('sha256',$id.'|'.$purpose.'|'.strtolower($email),ccv5_secret());return rtrim(strtr(base64_encode($id.'|'.$purpose.'|'.$sig),'+/','-_'),'=');}
function ccv5_parse_token(string $token): ?array {$raw=base64_decode(strtr($token,'-_','+/'),true);if(!$raw)return null;$p=explode('|',$raw);return count($p)===3&&ctype_digit($p[0])?[(int)$p[0],$p[1],$p[2]]:null;}
function ccv5_valid_manage(PDO $pdo,string $token): ?array {$p=ccv5_parse_token($token);if(!$p||$p[1]!=='manage')return null;$st=$pdo->prepare('SELECT * FROM surf_beta_subscribers WHERE id=? LIMIT 1');$st->execute([$p[0]]);$r=$st->fetch();if(!$r)return null;return hash_equals(ccv5_token((int)$r['id'],(string)$r['email'],'manage'),$token)?$r:null;}
function ccv5_client_ip(): string {$cf=(string)($_SERVER['HTTP_CF_CONNECTING_IP']??'');if($cf!==''&&filter_var($cf,FILTER_VALIDATE_IP))return $cf;$r=(string)($_SERVER['REMOTE_ADDR']??'unknown');return filter_var($r,FILTER_VALIDATE_IP)?$r:'unknown';}
function ccv5_http_json(string $url,int $timeout=8,array $headers=[]): ?array {
  if(!function_exists('curl_init'))return null;$ch=curl_init($url);$hs=array_merge(['Accept: application/json'],$headers);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_CONNECTTIMEOUT=>4,CURLOPT_TIMEOUT=>$timeout,CURLOPT_USERAGENT=>'CostaCamsSurfBeta/5.0 (+https://costacams.com)',CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_HTTPHEADER=>$hs]);$raw=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($raw===false||$code<200||$code>=400)return null;$j=json_decode((string)$raw,true);return is_array($j)?$j:null;
}
function ccv5_known_postcode(string $pc): ?array {
  $m=['4000'=>[-27.4698,153.0251,'Brisbane City'],'4215'=>[-27.9718,153.4066,'Southport'],'4216'=>[-27.9330,153.4010,'Runaway Bay / Biggera Waters'],'4217'=>[-28.0020,153.4280,'Surfers Paradise'],'4218'=>[-28.0397,153.4216,'Broadbeach / Mermaid Beach'],'4219'=>[-28.0710,153.4410,'Miami'],'4220'=>[-28.0870,153.4490,'Burleigh Heads'],'4221'=>[-28.1120,153.4660,'Palm Beach'],'4223'=>[-28.1450,153.4920,'Currumbin / Tugun'],'4224'=>[-28.1660,153.5150,'Bilinga / Kirra'],'4225'=>[-28.1730,153.5350,'Coolangatta'],'4226'=>[-28.0470,153.3540,'Robina'],'4227'=>[-28.0850,153.3780,'Reedy Creek'],'4228'=>[-28.1020,153.3370,'Tallebudgera Valley'],'4229'=>[-28.0930,153.4130,'Varsity Lakes'],'4230'=>[-28.0670,153.3930,'Merrimac'],'2481'=>[-28.6474,153.6020,'Byron Bay'],'2482'=>[-28.5530,153.5010,'Mullumbimby'],'2483'=>[-28.5260,153.5480,'Brunswick Heads / Ocean Shores'],'2484'=>[-28.3260,153.3940,'Murwillumbah'],'2485'=>[-28.1810,153.5400,'Tweed Heads'],'2486'=>[-28.2120,153.5450,'Tweed Heads South'],'2487'=>[-28.2570,153.5780,'Kingscliff'],'2488'=>[-28.3320,153.5720,'Cabarita / Bogangar'],'2489'=>[-28.2400,153.5560,'Pottsville / Tweed Coast']];return isset($m[$pc])?['lat'=>$m[$pc][0],'lon'=>$m[$pc][1],'label'=>$m[$pc][2]]:null;
