function ccv5_profile_defaults(array $p): array {
  $p=array_replace(cc_surf_profile_defaults(),$p);$p['session_minutes']=max(20,min(180,(int)($p['session_minutes']??40)));$p['buffer_minutes']=max(5,min(45,(int)($p['buffer_minutes']??10)));$p['time_mode']=in_array((string)($p['time_mode']??''),['finish_work','in_water','must_work'],true)?(string)$p['time_mode']:'finish_work';return $p;
}
function ccv5_road_times(array $spots,array $p): array {
  if(!is_numeric($p['origin_lat']??null)||!is_numeric($p['origin_lon']??null))return [];$olat=(float)$p['origin_lat'];$olon=(float)$p['origin_lon'];$coords=[sprintf('%.5f,%.5f',$olon,$olat)];$slugs=[];$fallback=[];
  foreach($spots as $s){$slugs[]=(string)$s['slug'];$coords[]=sprintf('%.5f,%.5f',(float)$s['lon'],(float)$s['lat']);$fallback[(string)$s['slug']]=cc_surf_travel_minutes($olat,$olon,(float)$s['lat'],(float)$s['lon']);}
  $idx=range(1,count($slugs));$url='https://router.project-osrm.org/table/v1/driving/'.implode(';',$coords).'?sources=0&destinations='.implode(';',$idx).'&annotations=duration';$j=ccv5_http_json($url,12);if(!$j||($j['code']??'')!=='Ok'||empty($j['durations'][0]))return $fallback;$out=[];foreach($slugs as $i=>$slug){$sec=$j['durations'][0][$i]??null;$out[$slug]=is_numeric($sec)?max(1,(int)round($sec/60)):$fallback[$slug];}return $out;
}
function ccv5_rank(array $spots,array $p): array {
  $p=ccv5_profile_defaults($p);$base=cc_surf_selected_epoch($p);$times=ccv5_road_times($spots,$p);$buf=(int)$p['buffer_minutes']*60;$sess=(int)$p['session_minutes']*60;$rows=[];
  foreach($spots as $s){$tr=$times[(string)$s['slug']]??null;$eval=$base;$plan=['travel'=>$tr,'in_water'=>$base,'leave_base'=>null,'leave_water'=>null,'arrive_back'=>null];if($tr!==null){$road=$tr*60;if($p['time_mode']==='finish_work'){$plan['leave_base']=$base;$plan['in_water']=$base+$road+$buf;$plan['leave_water']=$plan['in_water']+$sess;$plan['arrive_back']=$plan['leave_water']+$road+$buf;$eval=$plan['in_water'];}elseif($p['time_mode']==='in_water'){$plan['in_water']=$base;$plan['leave_base']=$base-$road-$buf;$plan['leave_water']=$base+$sess;$plan['arrive_back']=$plan['leave_water']+$road+$buf;$eval=$base;}else{$plan['arrive_back']=$base;$plan['leave_water']=$base-$road-$buf;$plan['in_water']=$plan['leave_water']-$sess;$plan['leave_base']=$plan['in_water']-$road-$buf;$eval=$plan['in_water']+(int)round($sess/2);}}$h=cc_surf_nearest_hour($s,$eval);if(!$h)continue;$sc=cc_surf_score($s,$h,$p);$rows[]=['spot'=>$s,'hour'=>$h,'score'=>$sc['score'],'reasons'=>$sc['reasons'],'travel_minutes'=>$tr,'eval_epoch'=>$eval,'plan'=>$plan];}
  usort($rows,fn($a,$b)=>$b['score']<=>$a['score']);return $rows;
}
function ccv5_clock(?int $epoch): string {if(!$epoch)return '—';return (new DateTimeImmutable('@'.$epoch))->setTimezone(new DateTimeZone('Australia/Brisbane'))->format('g:i A');}
function ccv5_plan_text(array $a,array $p): string {$pl=$a['plan'];$tr=$a['travel_minutes'];if($tr===null)return 'Travel time not included.';if($p['time_mode']==='finish_work')return 'Finish '.$p['session_hour'].' → drive ~'.$tr.' min + '.$p['buffer_minutes'].' min logistics → in water about '.ccv5_clock((int)$pl['in_water']).'.';if($p['time_mode']==='in_water')return 'Leave about '.ccv5_clock((int)$pl['leave_base']).' to be in the water at '.ccv5_clock((int)$pl['in_water']).'.';return 'Leave about '.ccv5_clock((int)$pl['leave_base']).', surf '.ccv5_clock((int)$pl['in_water']).'–'.ccv5_clock((int)$pl['leave_water']).', back by '.ccv5_clock((int)$pl['arrive_back']).'.';}
function ccv5_uv(float $u): string {if($u<3)return 'UV low';if($u<6)return 'UV moderate — SPF50+ water-resistant sunscreen recommended';if($u<8)return 'UV high — SPF50+ + UPF rashie';if($u<11)return 'UV very high — strong sun protection';return 'UV extreme — maximum sun protection';}
function ccv5_sample_html(array $rank,array $p): string {$top=array_slice($rank,0,3);$a=$top[0];$h=$a['hour'];$rows='';foreach($top as $i=>$x){$hh=$x['hour'];$rows.='<tr><td style="padding:9px;border-bottom:1px solid #e6e9ea">#'.($i+1).' <b>'.htmlspecialchars((string)$x['spot']['name']).'</b></td><td style="padding:9px;border-bottom:1px solid #e6e9ea">'.(int)$x['score'].'/100</td><td style="padding:9px;border-bottom:1px solid #e6e9ea">'.number_format((float)($hh['wave_height']??0),1).'m · '.round((float)($hh['wave_period']??0)).'s · '.htmlspecialchars((string)($hh['wind_compass']??'—')).' '.round((float)($hh['wind_speed']??0)).'km/h</td></tr>';}$plan=htmlspecialchars(ccv5_plan_text($a,$p),ENT_QUOTES,'UTF-8');return '<div style="font-family:Arial,sans-serif;max-width:660px;margin:auto;color:#172126"><div style="font-size:12px;font-weight:bold;color:#28798a">COSTACAMS · SAMPLE SURF BRIEF</div><h1>'.$a['spot']['name'].' · '.$a['score'].'/100</h1><p>This is a one-time example using your current profile. You are not subscribed by receiving this sample.</p><p><b>Plan:</b> '.$plan.'</p><p>🌊 '.number_format((float)($h['wave_height']??0),1).' m · '.round((float)($h['wave_period']??0)).' s &nbsp; ⚡ '.number_format((float)($h['energy_kwm']??0),1).' kW/m &nbsp; 💨 '.htmlspecialchars((string)($h['wind_compass']??'—')).' '.round((float)($h['wind_speed']??0)).' km/h</p><p>☀️ UV '.number_format((float)($h['uv']??0),1).' — '.htmlspecialchars(ccv5_uv((float)($h['uv']??0))).'</p><table style="border-collapse:collapse;width:100%;margin:16px 0">'.$rows.'</table><p><a style="display:inline-block;background:#0d6578;color:#fff;text-decoration:none;padding:11px 16px;border-radius:8px" href="https://costacams.com/ccdeploy-v3/costacams-v3/surf-match-beta-v5.php">Open Surf Match Beta</a></p><p style="font-size:11px;color:#778">Forecast/model guidance only. Check local conditions, lifeguards and your own ability before entering the water.</p></div>';}
function ccv5_mail(PDO $pdo,string $to,string $type,string $subject,string $html): array {
  $eh=hash('sha256',strtolower($to).'|'.ccv5_secret());$pdo->prepare("INSERT INTO surf_beta_mail_log(email_hash,mail_type,status,detail) VALUES(?,?, 'attempted','Hostinger Mail API')")->execute([$eh,$type]);$id=(int)$pdo->lastInsertId();$tokenFile='/home/u751177156/.ccmail-token';if(!is_readable($tokenFile)){$pdo->prepare("UPDATE surf_beta_mail_log SET status='failed',detail='Authenticated mail token unavailable' WHERE id=?")->execute([$id]);return ['accepted'=>false,'log_id'=>$id,'detail'=>'Authenticated mail transport is not ready.'];}$token=trim((string)file_get_contents($tokenFile));if($token==='')return ['accepted'=>false,'log_id'=>$id,'detail'=>'Authenticated mail token is empty.'];
