function ccv5_upsert_meta(PDO $pdo,string $email,array $p): void {$pc=preg_replace('/[^0-9]/','',(string)($p['origin_postcode']??''));$src=(string)($p['location_source']??($pc!==''?'postcode':(!empty($p['origin_lat'])?'browser':'')));$st=$pdo->prepare("INSERT INTO surf_beta_profile_meta(email,origin_postcode,origin_lat,origin_lon,location_source,schedule_mode,schedule_hour,session_minutes,buffer_minutes,height_cm,weight_kg,board_litres,profile_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE origin_postcode=VALUES(origin_postcode),origin_lat=VALUES(origin_lat),origin_lon=VALUES(origin_lon),location_source=VALUES(location_source),schedule_mode=VALUES(schedule_mode),schedule_hour=VALUES(schedule_hour),session_minutes=VALUES(session_minutes),buffer_minutes=VALUES(buffer_minutes),height_cm=VALUES(height_cm),weight_kg=VALUES(weight_kg),board_litres=VALUES(board_litres),profile_json=VALUES(profile_json),updated_at=NOW()");$st->execute([$email,$pc?:null,is_numeric($p['origin_lat']??null)?round((float)$p['origin_lat'],5):null,is_numeric($p['origin_lon']??null)?round((float)$p['origin_lon'],5):null,$src?:null,(string)$p['time_mode'],(float)$p['session_hour'],(int)$p['session_minutes'],(int)$p['buffer_minutes'],(int)($p['height_cm']??0)?:null,(int)($p['weight_kg']??0)?:null,is_numeric($p['board_litres']??null)?(float)$p['board_litres']:null,json_encode($p,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)]);}
function ccv5_manage_mail(PDO $pdo,array $r,string $reason='manage_link'): array {$base='https://costacams.com/ccdeploy-v3/costacams-v3/surf-match-beta-v5.php';$email=(string)$r['email'];$manage=$base.'?manage='.rawurlencode(ccv5_token((int)$r['id'],$email,'manage'));$unsub=$base.'?unsubscribe='.rawurlencode(ccv5_token((int)$r['id'],$email,'unsubscribe'));$html='<div style="font-family:Arial,sans-serif;max-width:620px;margin:auto;color:#172024"><h2>CostaCams Surf Profile</h2><p>Use your private link to edit your saved Surf Match profile.</p><p><a style="display:inline-block;padding:12px 18px;background:#0d6578;color:white;text-decoration:none;border-radius:8px" href="'.htmlspecialchars($manage).'">Edit my Surf Profile</a></p><p style="font-size:12px;color:#667">No password is required. Keep this link private.</p><p style="font-size:11px"><a href="'.htmlspecialchars($unsub).'">Unsubscribe</a></p></div>';return ccv5_mail($pdo,$email,$reason,'Your CostaCams Surf Profile link',$html);}

