if($action==='route_table'){$olat=filter_var($_POST['origin_lat']??null,FILTER_VALIDATE_FLOAT);$olon=filter_var($_POST['origin_lon']??null,FILTER_VALIDATE_FLOAT);$dest=json_decode((string)($_POST['destinations']??'[]'),true);if($olat===false||$olon===false||!is_array($dest)||count($dest)<1||count($dest)>40){http_response_code(422);echo json_encode(['ok'=>false,'message'=>'Invalid route request.']);exit;}$coords=[sprintf('%.5f,%.5f',$olon,$olat)];$slugs=[];$fallback=[];foreach($dest as $d){if(!is_array($d)||!isset($d['slug'],$d['lat'],$d['lon'])||!is_numeric($d['lat'])||!is_numeric($d['lon']))continue;$lat=(float)$d['lat'];$lon=(float)$d['lon'];$slug=(string)$d['slug'];$slugs[]=$slug;$coords[]=sprintf('%.5f,%.5f',$lon,$lat);$fallback[$slug]=['minutes'=>cc_surf_travel_minutes((float)$olat,(float)$olon,$lat,$lon),'distance_km'=>round(cc_surf_haversine_km((float)$olat,(float)$olon,$lat,$lon)*1.28,1)];}if(!$slugs){http_response_code(422);echo json_encode(['ok'=>false,'message'=>'No valid destinations.']);exit;}$idx=range(1,count($slugs));$url='https://router.project-osrm.org/table/v1/driving/'.implode(';',$coords).'?sources=0&destinations='.implode(';',$idx).'&annotations=duration,distance';$j=ccv5_http_json($url,12);$out=[];if($j&&($j['code']??'')==='Ok'&&!empty($j['durations'][0])){foreach($slugs as $i=>$slug){$sec=$j['durations'][0][$i]??null;$met=$j['distances'][0][$i]??null;if(is_numeric($sec))$out[$slug]=['minutes'=>max(1,(int)round($sec/60)),'distance_km'=>is_numeric($met)?round($met/1000,1):null];}echo json_encode(['ok'=>true,'source'=>'road_route','routes'=>$out]);exit;}echo json_encode(['ok'=>true,'source'=>'approximate','routes'=>$fallback]);exit;}

if($action==='sample'){
  if(!empty($_POST['website'])){echo json_encode(['ok'=>true]);exit;}$email=strtolower(trim((string)($_POST['email']??'')));if(!filter_var($email,FILTER_VALIDATE_EMAIL)){http_response_code(422);echo json_encode(['ok'=>false,'message'=>'Enter a valid email first.']);exit;}$eh=hash('sha256',$email.'|'.ccv5_secret());$ih=hash('sha256',ccv5_client_ip().'|'.ccv5_secret());$today=date('Y-m-d');$st=$pdo->prepare('SELECT sample_count FROM surf_beta_sample_log_v5 WHERE email_hash=? AND sample_date=?');$st->execute([$eh,$today]);if((int)($st->fetchColumn()?:0)>=1){http_response_code(429);echo json_encode(['ok'=>false,'message'=>'A sample has already been requested for this email today. Please check inbox/spam.']);exit;}$ipst=$pdo->prepare('SELECT COALESCE(SUM(sample_count),0) FROM surf_beta_sample_log_v5 WHERE ip_hash=? AND sample_date=?');$ipst->execute([$ih,$today]);if((int)$ipst->fetchColumn()>=3){http_response_code(429);echo json_encode(['ok'=>false,'message'=>'Sample limit reached for this connection today.']);exit;}$pdo->prepare('INSERT INTO surf_beta_sample_log_v5(email_hash,ip_hash,sample_date,sample_count,last_attempt_at) VALUES(?,?,?,1,NOW()) ON DUPLICATE KEY UPDATE sample_count=sample_count+1,last_attempt_at=NOW(),ip_hash=VALUES(ip_hash)')->execute([$eh,$ih,$today]);$p=json_decode((string)($_POST['profile']??'{}'),true);if(!is_array($p))$p=[];$p=ccv5_profile_defaults($p);$rank=ccv5_rank(cc_surf_load_spots($pdo),$p);if(!$rank){http_response_code(503);echo json_encode(['ok'=>false,'message'=>'Forecast unavailable. This sample attempt is locked for today to protect the service.']);exit;}$mail=ccv5_mail($pdo,$email,'sample_v5','Your CostaCams Surf Brief sample',ccv5_sample_html($rank,$p));if(!$mail['accepted']){http_response_code(503);echo json_encode(['ok'=>false,'message'=>'Authenticated email could not be sent. This attempt is locked for today to prevent abuse.']);exit;}echo json_encode(['ok'=>true,'message'=>'Sample sent through the authenticated CostaCams mailbox.